import json,re
P="partM.json"
d={i['file']:i for i in json.load(open(P))}
def add(f,extra):
    b=d[f]['body']; k=b.rindex('<h2>מה לעשות עכשיו')
    d[f]['body']=b[:k]+extra+"\n"+b[k:]
b=d["relocation-to-portugal.html"]; b['body']=b['body'].replace("<h2>איך מתכננים את לוח הזמנים לפורטוגל?</h2>\n","")
b=d["relocation-to-uk.html"]; b['body']=b['body'].replace("<h2>איך מתכננים שילוח לאנגליה בלי עיכובים?</h2>\n","")
b=d["relocation-to-germany.html"]; b['body']=b['body'].replace("<h2>איך מתכננים את לוח הזמנים לגרמניה?</h2>\n","")
add("relocation-to-portugal.html","""<p>גם הגעה בלי תכנון לתקופת ביניים היא טעות נפוצה. אם המטען מתעכב, צריך מקום לגור ודברים בסיסיים בשבוע הראשון. מי ששולח חלק באוויר מקצר את הפער הזה.</p>
<p>שימו לב לחפצים שיש להם ערך גבוה, כמו תכשיטים, עבודות אמנות ומכשירים יקרים. מצהירים עליהם בנפרד, ומומלץ לבדוק אם הביטוח מכסה אותם. בדרך כלל לא שולחים מסמכים מקוריים חשובים עם המכולה, אלא נושאים אותם אתכם.</p>""")
add("relocation-to-thailand.html","""<p>שאלה נוספת היא מה קורה בסוף השהייה. אם תחזרו לישראל, תצטרכו אולי להחזיר את החפצים, וגם לזה יש כללי מכס. לכן שמרו את רשימת התכולה ואת מסמכי הכניסה, כי הם יעזרו גם ביציאה.</p>
<p>הצוות שלנו יכול לבדוק איתכם מה כדאי לשלוח לפי משך השהייה שאתם מתכננים, ומה כדאי להשאיר בישראל באחסון.</p>""")
add("relocation-to-uk.html","""<p>כדאי להכין גם תוכנית לתקופת ביניים. אם הדירה עדיין לא מוכנה, או שהמטען מתעכב, צריך פתרון לשבועות הראשונים. אחסון זמני ביעד אפשרי, והעלות משתנה ונבדקת לכל מקרה.</p>
<p>ואל תשכחו את מה שנשאר מאחור: חפצים שאתם משאירים בישראל צריכים אחסון או מכירה. שילוח הוא רק חלק מהמעבר.</p>""")
add("relocation-to-germany.html","""<p>כדאי גם לשמור את כל המסמכים בקלסר אחד, נגיש ומסודר. המכס, חברת ההובלה והמשכיר עשויים לבקש העתקים. מי שמגיע עם מסמכים מסודרים חוסך זמן ועצבים.</p>
<p>אם אתם מביאים רהיטים גדולים, מדדו אותם מראש ובדקו שיעברו בפתח ובמדרגות של הדירה החדשה. דירות ישנות באירופה צרות לעיתים, ופריט שלא נכנס הוא כסף שירד לטמיון.</p>""")
add("relocation-what-they-dont-tell-you.html","""<p>דבר נוסף שלא מדברים עליו הוא הצד הרגשי. אריזת בית שלם היא עבודה מתישה, ולכן מתחילים מוקדם ומחלקים לשלבים: קודם מה שלא משתמשים בו, ובסוף מה שצריך עד הרגע האחרון.</p>
<p>ושאלו על תנאי הפריקה ביעד. לא תמיד נכלל סיוע בהכנסה לדירה, בהרכבת רהיטים או בפינוי חומרי האריזה. את התשובות רושמים בכתב, כדי שלא תהיה אי הבנה אחר כך.</p>""")
add("airspace-closed-shipping.html","""<p>גם בצד של יבוא אפשר לפעול. אם סחורה מחו"ל מחכה לטיסה לישראל, בררו אם המוביל מציע להמתין, לעבור לים או לנתב מחדש. כל אפשרות משפיעה על העלות ועל מסמכי המכס, ולכן מחליטים בעזרת הצוות.</p>
<p>מי שמוכר ללקוחות פרטיים צריך לשמור על שקיפות. הודעה ברורה על עיכוב מצמצמת פניות חוזרות וביטולים, ובונה אמון לטווח ארוך.</p>""")
json.dump(list(d.values()),open(P,"w"),ensure_ascii=False,indent=1)
